sys_ux_client_script.script:
function handler({api, event, helpers, imports}) {

    // Get the current lap list
    const laps = api.state.lapTimes || [];

    // Get the current stopwatch time
    const currentTime = api.state.elapsedTime;

    // Create the new lap
    const newLap = {
        lap: laps.length + 1,
        time: currentTime
    };

    // Add the new lap to the existing list
    const updatedLaps = [...laps, newLap];

    // Save the updated lap list
    api.setState('lapTimes', updatedLaps);
}
